<?php require __DIR__.'/includes/bootstrap.php';require_login();$pageTitle='My Profile';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='profile'){$name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);if($name===''||!$email)throw new RuntimeException('Enter a name and valid email.');db()->prepare('UPDATE users SET name=?,email=? WHERE id=?')->execute([$name,$email,current_user()['id']]);$_SESSION['user']['name']=$name;$_SESSION['user']['email']=$email;flash('success','Profile updated.');redirect('profile.php');}elseif($action==='password'){$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$s=db()->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([current_user()['id']]);if(!password_verify($old,(string)$s->fetchColumn()))throw new RuntimeException('Current password is incorrect.');if(strlen($new)<12)throw new RuntimeException('New password must be at least 12 characters.');if($new!==$confirm)throw new RuntimeException('Password confirmation does not match.');db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),current_user()['id']]);session_regenerate_id(true);flash('success','Password changed successfully.');redirect('profile.php');}}catch(Throwable $e){$error=$e->getMessage();}}require __DIR__.'/includes/header.php';?><h1>My Profile</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="panel"><h2>Profile details</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="profile"><div class="field"><label>Name</label><input name="name" required value="<?=e(current_user()['name'])?>"></div><div class="field"><label>Email</label><input type="email" name="email" required value="<?=e(current_user()['email'])?>"></div><button>Update profile</button></form></section><section class="panel"><h2>Change password</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="password"><?php foreach(['old_password'=>'Current password','new_password'=>'New password (12+ characters)','confirm_password'=>'Confirm new password'] as $name=>$label):?><div class="field"><label><?=e($label)?></label><input type="password" name="<?=e($name)?>" required <?=$name!=='old_password'?'minlength="12"':''?> autocomplete="new-password"></div><?php endforeach;?><button>Change password</button></form></section><?php require __DIR__.'/includes/footer.php'; ?>